from solution import fit

def test_examples():
    assert fit('hello world', 8) == 'hello w…'
    assert fit('hello', 5) == 'hello'

def test_wide_boundary():
    assert fit('你好吗', 4) == '你…'
    assert fit('你好吗', 5) == '你好…'
    assert fit('你好', 4) == '你好'

def test_width_one():
    assert fit('abc', 1) == '…'
    assert fit('a', 1) == 'a'
    assert fit('你', 1) == '…'

def test_combining_stays():
    assert fit('abe\u0301cd', 4) == 'abe\u0301…'
    assert fit('abe\u0301cd', 3) == 'ab…'

def test_fits_with_combining():
    s = 'e\u0301e\u0301e\u0301'
    assert fit(s, 3) == s

def test_zwj():
    s = 'a\u200db\u200dc'
    assert fit(s, 2) == 'a\u200d…'
    assert fit(s, 3) == s

def test_emoji():
    assert fit('😀😀😀', 5) == '😀😀…'
    assert fit('😀😀😀', 4) == '😀…'

def test_fullwidth():
    assert fit('ＡＢＣ', 5) == 'ＡＢ…'

def test_hangul():
    assert fit('한국어입니다', 6) == '한국…'

def test_empty():
    assert fit('', 1) == ''
